widget.solution:
#include <algorithm>

class Call : public Payoff {
public:
    explicit Call(double strike) : strike_(strike) {}
    double operator()(double spot) const override { return std::max(spot - strike_, 0.0); }
private:
    double strike_;
};

class Put : public Payoff {
public:
    explicit Put(double strike) : strike_(strike) {}
    double operator()(double spot) const override { return std::max(strike_ - spot, 0.0); }
private:
    double strike_;
};

class DigitalCall : public Payoff {
public:
    DigitalCall(double strike, double cash) : strike_(strike), cash_(cash) {}
    double operator()(double spot) const override { return spot > strike_ ? cash_ : 0.0; }
private:
    double strike_;
    double cash_;
};

