#include <algorithm>

class CappedCall : public Payoff {
public:
    CappedCall(double strike, double cap) : strike_(strike), cap_(cap) {}
    double operator()(double spot) const override {
        return std::min(std::max(spot - strike_, 0.0), cap_);
    }
private:
    double strike_;
    double cap_;
};

